// Block-reading loop sketch (hot path: no allocations, no iostreams).
char buf[1 << 18];
std::size_t len = 0;                       // bytes of the pending partial line
while (true) {
    std::size_t got = std::fread(buf + len, 1, sizeof(buf) - len, stdin);
    if (got == 0) {
        if (len > 0) processLine(buf, len);   // final line without '\n'
        break;
    }
    std::size_t start = 0;
    for (std::size_t i = 0; i < len + got; ++i) {
        if (buf[i] == '\n') { processLine(buf + start, i - start); start = i + 1; }
    }
    len = len + got - start;
    std::memmove(buf, buf + start, len);      // carry partial line to front
}

