#pragma once
// Numerically stable online statistics (Welford's algorithm).
// Single pass, O(1) memory: suitable for unbounded log streams.

#include <cmath>
#include <cstddef>

namespace logproc {

class Welford {
public:
    void add(double x) {
        if (n_ == 0) {
            min_ = x;
            max_ = x;
        } else {
            if (x < min_) min_ = x;
            if (x > max_) max_ = x;
        }
        ++n_;
        const double delta = x - mean_;
        mean_ += delta / static_cast<double>(n_);
        m2_ += delta * (x - mean_);
    }

    std::size_t count() const { return n_; }
    double mean() const { return mean_; }

    // Population variance of the values seen so far (divide by N).
    double variance() const {
        return n_ > 0 ? m2_ / static_cast<double>(n_) : 0.0;
    }
    double stddev() const { return std::sqrt(variance()); }

    double min() const { return min_; }
    double max() const { return max_; }

private:
    std::size_t n_ = 0;
    double mean_ = 0.0;
    double m2_ = 0.0;
    double min_ = 0.0;
    double max_ = 0.0;
};

}  // namespace logproc

// logproc: high-throughput streaming log processor.
// TODO(project): implement the full pipeline described in the project brief.
//   1) read stdin in large blocks (fread), split into lines;
//   2) parse "timestamp_ms,service,value" with std::from_chars (no iostreams in the hot path);
//   3) feed each value into the per-service Welford accumulator (include/logproc/welford.hpp);
//   4) at EOF print per-service summary to stdout and anomalies to stderr.
// The starter below only counts lines to verify the build and I/O plumbing.

#include <cstdio>

#include "logproc/welford.hpp"  // prove the include path resolves

int main() {
    char buf[1 << 16];
    unsigned long long lines = 0;
    while (std::fgets(buf, sizeof buf, stdin) != nullptr) {
        ++lines;
    }
    std::printf("lines=%llu\n", lines);
    return 0;
}
